(function(){
  function bench(code, iters){
    iters=Math.max(1, parseInt(iters,10)||10);
    var fn;
    try{ fn=new Function(code); }catch(e){ return {error:'代码编译失败: '+e.message}; }
    var times=[];
    for(var i=0;i<iters;i++){
      var t0=performance.now();
      try{ fn(); }catch(e){ return {error:'运行出错: '+e.message}; }
      var t1=performance.now();
      times.push(t1-t0);
    }
    times.sort(function(a,b){return a-b;});
    var sum=times.reduce(function(a,b){return a+b;},0);
    var mean=sum/times.length;
    var sq=times.reduce(function(a,b){return a+Math.pow(b-mean,2);},0);
    var std=Math.sqrt(sq/times.length);
    return {value:{min:times[0], max:times[times.length-1], mean:mean, median:times[Math.floor(times.length/2)], stddev:std, iters:iters, times:times}};
  }
  var API={bench:bench};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__HyperfineForge__=API;
})();
